B.acT=new A.bg("B\u1ea1n ch\u01b0a g\u1eedi y\xeau c\u1ea7u n\xe0o.",B.G,null)
B.acU=new A.bg("H\u1ecfi \u0111\xe1p m\u1eabu t\u1eeb n\u1ed9i dung b\u1ed9 s\u01b0u t\u1eadp. Tr\u1ee3 l\xfd th\xf4ng minh s\u1ebd \u0111\u01b0\u1ee3c k\u1ebft n\u1ed1i sau.",B.G,null)
