B.acW=new A.bg("C\xe0i \u0111\u1eb7t v\xe0 d\u1eef li\u1ec7u ch\u1ec9 \u0111\u01b0\u1ee3c gi\u1eef trong phi\xean tr\u1ea3i nghi\u1ec7m hi\u1ec7n t\u1ea1i.",B.G,null)
B.acY=new A.bg("Nh\u1eadp m\xe3 do ng\u01b0\u1eddi mua g\xf3i nh\xf3m chia s\u1ebb \u0111\u1ec3 nh\u1eadn quy\u1ec1n truy c\u1eadp.",B.G,null)
B.acZ=new A.bg("Gi\xe1 v\xe0 th\u1eddi h\u1ea1n \u0111\u01b0\u1ee3c m\xe1y ch\u1ee7 x\xe1c nh\u1eadn khi t\u1ea1o \u0111\u01a1n. Quy\u1ec1n truy c\u1eadp ch\u1ec9 \u0111\u01b0\u1ee3c c\u1ea5p sau khi m\xe1y ch\u1ee7 x\xe1c nh\u1eadn thanh to\xe1n.",B.G,null)
B.ad_=new A.bg("Xem hi\u1ec7n v\u1eadt n\u1eb1m \u1edf ph\xf2ng v\xe0 t\u1ea7ng n\xe0o. Qu\xe9t QR t\u1ea1i v\u1ecb tr\xed \u0111ang \u0111\u1ee9ng \u0111\u1ec3 t\xecm \u0111\u01b0\u1eddng tr\xean s\u01a1 \u0111\u1ed3.",B.G,null)
B.ad0=new A.bg("Ch\u01b0a c\xf3 b\u1ea3o t\xe0ng c\xf4ng khai.",B.G,null)
B.ad1=new A.bg("\u0110\xe3 ghi nh\u1eadn l\u01b0\u1ee3t qu\xe9t. C\xe2u \u0111\u1ed1 v\xe0 \u0111i\u1ec3m \u0111\u01b0\u1ee3c h\u1ec7 th\u1ed1ng c\u1eadp nh\u1eadt n\u1ebfu \u0111\u1ee7 \u0111i\u1ec1u ki\u1ec7n.",B.G,null)
