B.ad9=new A.bg("Hi\u1ec7n v\u1eadt m\u1eabu ch\u01b0a c\xf3 v\u1ecb tr\xed trong b\u1ea3o t\xe0ng th\u1ef1c t\u1ebf.",B.G,null)
B.adb=new A.bg("\u0110\xe1nh gi\xe1 b\u1ea3o t\xe0ng c\u1ea7n g\u1eafn v\u1edbi l\u01b0\u1ee3t tham quan \u0111\xe3 ho\xe0n th\xe0nh. G\xf3p \xfd chung s\u1ebd \u0111\u01b0\u1ee3c g\u1eedi \u0111\u1ebfn b\u1ed9 ph\u1eadn h\u1ed7 tr\u1ee3.",B.G,null)
